using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n; if(!(cin>>n)) return 0;
    vector<string> a(n+1);
    for(int i=1;i<=n;++i){ cin>>a[i]; }

    // Map substring code (base-27 encoding) to list of string indices that contain it
    unordered_map<uint64_t, vector<int>> mp; mp.reserve(600000);

    for(int i=1;i<=n;++i){
        const string &s = a[i]; int L = (int)s.size();
        vector<uint64_t> codes; codes.reserve(L*(L+1)/2);
        for(int l=0;l<L;++l){
            uint64_t code = 0;
            for(int r=l; r<L; ++r){
                code = code*27 + (uint64_t)(s[r]-'a'+1);
                codes.push_back(code);
            }
        }
        sort(codes.begin(), codes.end());
        codes.erase(unique(codes.begin(), codes.end()), codes.end());
        for(uint64_t c: codes){ mp[c].push_back(i); }
    }

    int Q; cin>>Q;
    while(Q--){
        int Lq, Rq; string str; cin>>Lq>>Rq>>str;
        if(Lq > Rq){ // handle edge case gracefully
            cout << 0 << '\n';
            continue;
        }
        uint64_t code = 0;
        for(char ch: str) code = code*27 + (uint64_t)(ch-'a'+1);
        auto it = mp.find(code);
        if(it == mp.end()){
            cout << 0 << '\n';
        } else {
            const vector<int> &vec = it->second;
            int cnt = (int)(upper_bound(vec.begin(), vec.end(), Rq) - lower_bound(vec.begin(), vec.end(), Lq));
            cout << cnt << '\n';
        }
    }
    return 0;
}
