from fractions import Fraction

def brute(n, k):
    p = Fraction(1, k)
    dist = {1: Fraction(1,1)}
    total = Fraction(0,1)
    for s in range(1, n+1):
        step = Fraction(0,1)
        for t, prob in dist.items():
            rt = Fraction(t*(t+3), 2*(t+1))
            step += prob * rt
        total += step * p
        new = {}
        for t, prob in dist.items():
            inc = Fraction(p, t+1)
            stay = 1 - inc
            m1 = prob * stay
            m2 = prob * inc
            new[t] = new.get(t, Fraction(0,1)) + m1
            new[t+1] = new.get(t+1, Fraction(0,1)) + m2
        dist = {t: prob for t, prob in new.items() if prob > 0}
    return total

for n in range(1,7):
    for k in range(1,4):
        val = brute(n,k)
